/bin/bash -lc "node --input-type=module <<'EOF'
import { spawnSync } from 'node:child_process';

const cases = [
  [],
  ['--help'],
  ['--a', \"DELETE FROM logs WHERE created_at < '2022-01-01'; DELETE FROM temp_data WHERE processed = true; TRUNCATE TABLE session_data\"],
  ['--b', 'x'],
  ['--a', 'x', '--b', 'y'],
  ['--a'],
  ['--a='],
  ['--a', '-1'],
  ['--a', '-x'],
  ['--a', \"SELECT ';' AS x; SELECT 1\"],
  ['--a', 'BEGIN SELECT 1; SELECT 2; END; SELECT 3'],
  ['--a', 'BEGIN; SELECT 1; END; SELECT 2'],
  ['--a', 'SELECT 1; -- c\\n-- d\\nSELECT 2'],
  ['--a', 'SELECT 1; /* c */\\nSELECT 2'],
  ['--a', 'DO "'$tag$ begin; end; $tag$; SELECT 2'"'],
  ['--a', 'CASE WHEN 1=1 THEN 1; END; SELECT 2'],
];

let failed = 0;

for (const args of cases) {
  const py = spawnSync('/workspace/dataset/test2_executable', args, { encoding: 'utf8' });
  const js = spawnSync('node', ['/output/test2.mjs', ...args], { encoding: 'utf8' });

  const normalizedPyStdout = py.stdout.replaceAll('test2_executable', 'test2.mjs');
  const normalizedPyStderr = py.stderr.replaceAll('test2_executable', 'test2.mjs');

  const ok = py.status === js.status && normalizedPyStdout === js.stdout && normalizedPyStderr === js.stderr;

  if ("'!ok) {
    failed += 1;
    console.log(JSON.stringify({ args, py: { status: py.status, stdout: normalizedPyStdout, stderr: normalizedPyStderr }, js: { status: js.status, stdout: js.stdout, stderr: js.stderr } }, null, 2));
  }
}

if (failed === 0) {
  console.log('"'ALL_CASES_MATCHED');
} else {
  process.exitCode = 1;
}
EOF"

